          end if
        end repeat
      else
        -- Return the error from starting the tests
        return startResult
      end if
    on error errMsg
      return "{\"error\": true, \"message\": \"" & my escapeJSString(errMsg) & "\"}"
    end try
  end tell
end runChromeTests

